import{_ as l,o,c as n,a5 as i}from"./chunks/framework.Cooo9kuv.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"881-PDF重命名工具-提取框选区域文本-只支持文本pdf","日期":"2026-04-14T00:00:00.000Z","修改日期":"2026-04-14T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["PDF批处理"],"标签":["PDF批量处理工具","PDF文件管理","PDF文本提取","PDF重命名工具","Python PDF工具","发票批量处理","批量重命名PDF","文件整理助手","文档自动命名","模板化重命名"]},"headers":[],"relativePath":"md/PDF批处理/881-PDF重命名工具-提取框选区域文本-只支持文本pdf.md","filePath":"md/PDF批处理/881-PDF重命名工具-提取框选区域文本-只支持文本pdf.md"}'),r={name:"md/PDF批处理/881-PDF重命名工具-提取框选区域文本-只支持文本pdf.md"};function s(p,t,a,g,e,h){return o(),n("div",null,[...t[0]||(t[0]=[i('<p>PDF重命名工具用于从PDF文件中提取指定区域的文本内容，并将其作为文件名进行重命名。该工具特别适用于批量处理发票、合同、报告等格式统一的PDF文档，能够大幅提高文件整理效率。</p><p>工具采用模板化设计，用户可以通过可视化界面框选需要提取的文本区域，保存为模板后即可批量应用于相同格式的PDF文件。支持单文件处理和文件夹批量处理，并可选择是否递归处理子文件夹中的文件。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260210223317177073399745002.png" alt=""></p><h3 id="功能特点" tabindex="-1">功能特点 <a class="header-anchor" href="#功能特点" aria-label="Permalink to &quot;功能特点&quot;">​</a></h3><p><strong>核心功能特点：</strong></p><ul><li>可视化框选提取 - 图形化PDF预览界面，鼠标框选需要提取的文本区域，用来重命名pdf文件</li><li>模板管理 - 支持创建、复制、删除、重命名多个模板，适应不同格式的PDF文件</li><li>批量处理 - 支持单文件或整个文件夹的批量重命名处理</li><li>递归子文件夹 - 可选择是否穿透处理子文件夹中的所有PDF文件</li><li>拖放支持 - 支持将文件或文件夹直接拖放到输入框中</li><li>文件名冲突处理 - 自动处理重命名时的文件名冲突，添加序号避免覆盖，名称后添加_1...这样的数字序列避免重复</li></ul><h3 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h3><p><strong>快速上手步骤：</strong></p><ol><li>启动程序 - 运行源代码.py文件，打开主界面</li><li>创建模板 - 切换到”模板定制”标签页，点击”新建”按钮创建新模板</li><li>加载示例PDF - 点击”加载PDF”按钮，选择一个格式标准的PDF文件</li><li>框选提取区域 - 在PDF预览界面中，用鼠标拖拽框选需要提取的文本区域（如发票号码、日期等）</li><li>保存模板 - 点击”保存模板”按钮，保存当前框选区域</li><li>批量处理 - 切换到”处理”标签页，选择要处理的文件夹，选择刚才创建的模板，点击”开始重命名”</li><li>查看结果 - 处理完成后，查看处理日志和重命名结果</li></ol><h3 id="详细使用说明" tabindex="-1">详细使用说明 <a class="header-anchor" href="#详细使用说明" aria-label="Permalink to &quot;详细使用说明&quot;">​</a></h3><p><strong>处理标签页功能说明：</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260210224917177073495758246.png" alt=""></p><ul><li><strong>输入路径</strong> - 支持输入单个PDF文件路径或包含PDF文件的文件夹路径，支持拖放操作</li><li><strong>模板选择</strong> - 下拉框选择已创建的模板，点击”管理模板”可跳转到模板定制页面</li><li><strong>穿透子文件夹</strong> - 勾选后将递归处理所有子文件夹中的PDF文件</li><li><strong>开始重命名</strong> - 开始执行批量重命名操作</li><li><strong>清除日志</strong> - 清空处理日志区域</li><li><strong>进度条</strong> - 实时显示当前处理进度</li></ul><p><strong>模板定制标签页功能说明：</strong></p><ul><li><strong>模板列表</strong> - 左侧显示所有已创建的模板，支持选择、新建、复制、删除、重命名操作</li><li><strong>PDF查看器</strong> - 右侧显示PDF文件内容，支持翻页、缩放、滚动查看</li><li><strong>框选区域</strong> - 在PDF预览界面中用鼠标拖拽创建框选区域，可创建多个区域</li><li><strong>清除框选</strong> - 清除当前页面的所有框选区域</li><li><strong>加载PDF</strong> - 加载PDF文件用于创建或编辑模板</li><li><strong>保存模板</strong> - 将当前框选区域保存到选中的模板中</li></ul><p><strong>PDF查看器操作说明：</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260210224832177073491230373.jpg" alt=""></p><ul><li><strong>翻页</strong> - 点击”上一页”或”下一页”按钮切换页面</li><li><strong>滚动</strong> - 使用鼠标滚轮或滚动条查看页面内容</li><li><strong>框选</strong> - 按住鼠标左键拖拽创建框选区域</li><li><strong>清除框选</strong> - 点击”清除框选”按钮删除所有框选区域</li></ul><h3 id="使用场景示例" tabindex="-1">使用场景示例 <a class="header-anchor" href="#使用场景示例" aria-label="Permalink to &quot;使用场景示例&quot;">​</a></h3><p><strong>场景一：批量重命名发票文件</strong></p><p>某公司财务部门收到大量电子发票文件，文件名均为随机字符，需要按照发票号码进行整理。</p><ol><li>打开程序，切换到”模板定制”标签页</li><li>新建模板命名为”发票模板”</li><li>加载一张标准格式的发票PDF文件</li><li>在预览界面中框选发票号码区域</li><li>保存模板</li><li>切换到”处理”标签页</li><li>选择包含所有发票文件的文件夹</li><li>选择”发票模板”</li><li>点击”开始重命名”</li><li>程序自动提取每张发票的号码并重命名文件</li></ol><p><strong>场景二：合同文件按日期归档</strong></p><p>法务部门需要将大量合同文件按签订日期进行归档管理。</p><ol><li>在”模板定制”中创建”合同模板”</li><li>加载一份合同样本文件</li><li>框选合同签订日期区域</li><li>保存模板</li><li>在”处理”标签页选择合同文件夹</li><li>选择”合同模板”</li><li>勾选”穿透子文件夹”（如果合同分布在多个子文件夹）</li><li>开始处理，所有合同文件将按日期重命名</li></ol><p><strong>场景三：报告文件按标题分类</strong></p><p>研究机构需要将大量研究报告按报告标题进行分类整理。</p><ol><li>创建”报告模板”</li><li>加载一份报告样本</li><li>框选报告标题区域</li><li>保存模板</li><li>选择报告文件夹</li><li>使用模板批量处理</li><li>所有报告文件将按标题重命名，便于检索和分类</li></ol><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><p><strong>重要警告：</strong></p><ul><li>备份重要文件 - 在进行批量重命名操作前，建议先备份原始文件，避免误操作导致数据丢失</li><li><strong>模板格式一致性 - 确保所有要处理的PDF文件格式与模板创建时使用的样本文件格式一致，否则可能导致提取失败或提取错误</strong></li><li>文件名长度限制 - 提取的文件名会被限制在100个字符以内，超出部分将被截断</li><li>非法字符处理 - 程序会自动移除文件名中的非法字符（如&lt;&gt;:”/|?*），但建议了解此行为</li><li>文件占用问题 - 确保要处理的PDF文件未被其他程序打开，否则可能导致重命名失败</li><li>模板文件位置 - 模板数据保存在程序同目录下的invoice_templates.json文件中，请勿删除或手动修改此文件</li><li>子文件夹递归 - 勾选”穿透子文件夹”后，程序会处理所有子文件夹中的PDF文件，请确保这是预期行为</li></ul><h3 id="程序截图" tabindex="-1">程序截图 <a class="header-anchor" href="#程序截图" aria-label="Permalink to &quot;程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260210223317177073399745002.png" alt=""></p><h3 id="常见问题解答" tabindex="-1">常见问题解答 <a class="header-anchor" href="#常见问题解答" aria-label="Permalink to &quot;常见问题解答&quot;">​</a></h3><p><strong>Q: 框选区域后提取的文本为空是什么原因？</strong></p><p>A: 可能的原因包括：框选区域没有覆盖到文本、PDF文件是扫描图片而非可提取文本的PDF、PDF文件格式特殊。</p><p><strong>Q: 批量处理时部分文件失败怎么办？</strong></p><p>A: 查看处理日志中的错误信息。常见原因包括：文件被占用、文件格式与模板不匹配、PDF文件损坏。建议检查失败文件的具体情况。</p><p><strong>Q: 如何处理文件名冲突？</strong></p><p>A: 程序会自动在文件名后添加序号（如_1、_2等）来避免冲突。如果重命名后文件名已存在，程序会自动递增序号直到找到可用的文件名。</p><p><strong>Q: 可以同时框选多个区域吗？</strong></p><p>A: 不可以</p><p><strong>Q: 模板可以复制吗？</strong></p><p>A: 可以。在模板列表中选择要复制的模板，点击”复制”按钮，输入新模板名称即可创建副本。</p><p><strong>Q: 如何删除不需要的模板？</strong></p><p>A: 在模板列表中选择要删除的模板，点击”删除”按钮。注意：默认模板不能删除。</p><p><strong>Q: 程序支持哪些操作系统？</strong></p><p>A: 程序支持Windows7及以上64位windows操作系统</p><p><strong>Q: 处理大量文件时程序会卡顿吗？</strong></p><p>A: 程序使用多线程处理，不会卡顿主界面。处理过程中会实时显示进度条和日志，可以随时查看处理状态。</p><p><strong>Q: 提取的文本包含多余标点怎么办？</strong></p><p>A: 程序内置了文本清理功能，会自动移除多余的标点和空白。如果仍有问题，可以在模板中调整框选区域以避免包含不需要的标点。</p><p><strong>Q: 可以递归处理子文件夹吗？</strong></p><p>A: 可以。在处理标签页勾选”穿透子文件夹”选项，程序将递归处理所有子文件夹中的PDF文件。</p><p><strong>Q: 模板文件保存在哪里？</strong></p><p>A: 模板数据保存在程序同目录下的invoice_templates.json文件中。建议定期备份此文件以防数据丢失。</p><p><strong>Q: 如何恢复默认模板？</strong></p><p>A: 如果误删了默认模板，可以删除invoice_templates.json文件，程序会自动重新创建包含默认模板的文件。</p><p><strong>Q: 程序支持拖放文件吗？</strong></p><p>A: 支持。您可以将PDF文件或文件夹直接拖放到输入路径框中，程序会自动识别并填入路径。</p><p><strong>Q: 处理过程中可以中断吗？</strong></p><p>A: 当前版本不支持中途中断处理。</p><p><strong>Q: 提取的文件名太长怎么办？</strong></p><p>A: 程序会自动将文件名限制在100个字符以内。如果需要更短的文件名，可以调整框选区域以减少提取的文本量。</p><h3 id="程序使用环境及相关说明" tabindex="-1">程序使用环境及相关说明 <a class="header-anchor" href="#程序使用环境及相关说明" aria-label="Permalink to &quot;程序使用环境及相关说明&quot;">​</a></h3><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统 ，  **注意事项：**win32位系统以及mac系统需要额外定制开发</p><p><strong>2、关于使用限制</strong>：①无需注册、登录等限制，直接使用，  ②没有电脑台数限制，  ③无使用时间限制、不联网本地使用、确保数据安全</p><p><strong>3、程序如何安装</strong>：不需要安装，按照说明使用即可。</p><p><strong>特别注意</strong>：请先测试，注意备份原文件，之后再批量使用，避免不可逆损失。</p><h3 id="程序使用说明" tabindex="-1">程序使用说明 <a class="header-anchor" href="#程序使用说明" aria-label="Permalink to &quot;程序使用说明&quot;">​</a></h3><p><strong>解压后，双击快捷方式使用即可</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260210224644177073480418898.png" alt=""></p><p><strong>如果快捷方式失效，打开文件夹，找到如下文件，重新创建快捷方式使用即可</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260210224655177073481592780.png" alt=""></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2472.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2472.html</a></p>',76)])])}const d=l(r,[["render",s]]);export{c as __pageData,d as default};
